sysauto_script.script:
// PerfPulse — Daily Delta Scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function () {
    var engine = new PerfPulseEngine();
    var scanId = engine.runScan('delta', 'local');
    if (scanId) {
        gs.info('PerfPulse daily scan completed: ' + scanId);
    } else {
        gs.error('PerfPulse daily scan failed to start');
    }
})();
